{"implementation":"def solve(case):
    nodes = case['nodes']
    required = set(case['required_symbols'])
    node_map = {n['id']: n for n in nodes}
    children = {n['id']: [] for n in nodes}
    for n in nodes:
        p = n.get('parent')
        if p is not None:
            children[p].append(n['id'])
    retained = set(node_map.keys())
    sym_ids = {}
    for n in nodes:
        s = n['symbol']
        sym_ids.setdefault(s, set()).add(n['id'])
    for s in required:
        if s not in sym_ids or not sym_ids[s]:
            raise ValueError(f"missing required symbol: {s}")
    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))
    removed = []
    for n in sorted_nodes:
        nid = n['id']
        if n['parent'] is None:
            continue
        if not n.get('removable', False):
            continue
        if any(c in retained for c in children.get(nid, [])):
            continue
        retained.remove(nid)
        ok = True
        for s in required:
            if not any(oid in retained for oid in sym_ids.get(s, set())):
                ok = False
                break
        if ok:
            removed.append(nid)
        else:
            retained.add(nid)
    retained_sorted = sorted(retained)
    return {
        'removed_node_ids': removed,
        'retained_node_ids': retained_sorted
    }"}
